import os


def _list_files(path: str = ".") -> list:
    return os.listdir(path)


def _read_file(path: str) -> str:
    with open(path, "r") as f:
        return f.read()


def _count_lines(path: str) -> str:
    with open(path, "r") as f:
        return str(len(f.read().splitlines()))


TOOLS = {
    "list_files": _list_files,
    "read_file": _read_file,
    "count_lines": _count_lines,
}


def execute_tool(name: str, args: dict) -> str:
    tool = TOOLS.get(name)
    if tool is None:
        return f"Error: unknown tool '{name}'"
    return tool(**args)


# Test
try:
    result = execute_tool("count_lines", {"path": "test.txt"})
except (FileNotFoundError, OSError):
    result = None

print(f"Tool registry with {len(TOOLS)} tools and a working dispatcher")

def agent_step(messages: list, mock_llm, tools: dict):
    response = mock_llm(messages)
    if response.get('done'):
        return response.get('content')
    call = response['tool_call']
    name = call['name']
    args = call.get('args', {})
    result = tools[name](**args)
    messages.append({'role': 'assistant', 'content': None, 'tool_call': call})
    messages.append({'role': 'tool', 'name': name, 'content': result})
    return None


msgs = [{'role': 'user', 'content': 'test'}]
mock = lambda m: {'done': False, 'tool_call': {'name': 'echo', 'args': {'text': 'hi'}}}
tools = {'echo': lambda text: text.upper()}
result = agent_step(msgs, mock, tools)
assert result is None
assert len(msgs) == 3
assert msgs[-1]['content'] == 'HI'
mock_done = lambda m: {'done': True, 'content': 'All done'}
assert agent_step(msgs, mock_done, tools) == 'All done'
